function roleButtonExample() {
  const roleButton = document.getElementById("roleButton");
  const roleButtonOndark = document.getElementById("roleButton-ondark");

  const handleAction = () => {
    alert("You clicked the role button!");
  };

  // Enter and Space don't fire `click` on the link, so handle those keys too.
  const handleKeydown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      handleAction();
    }
  };

  for (const button of [roleButton, roleButtonOndark]) {
    button.addEventListener("click", handleAction);
    button.addEventListener("keydown", handleKeydown);
  }
}

AuroHyperlink.register();

function initHyperlinkApiExamples(initCount) {
  // biome-ignore lint: no-unused-vars
  initCount = initCount || 0;

  try {
    roleButtonExample();
  } catch {
    if (initCount <= 20) {
      // setTimeout handles issue where content is sometimes loaded after the functions get called
      setTimeout(() => {
        initHyperlinkApiExamples(initCount + 1);
      }, 100);
    }
  }
}

initHyperlinkApiExamples();
